mapper.select:
        SELECT


--         级联表的字段

        FROM assessment_paper  a



                and a.id in

                #{item}



                and a.name like CONCAT('%',#{params.name},'%')


                  and a.duration_minutes >= #{params.exampaperDateStart}   


                  and a.duration_minutes <= #{params.exampaperDateEnd}   


                and a.duration_minutes = #{params.durationMinutes}


                  and a.total_score >= #{params.exampaperMyscoreStart}   


                  and a.total_score <= #{params.exampaperMyscoreEnd}   


                and a.total_score = #{params.totalScore}


                and a.status = #{params.status}


                  and a.is_deleted >= #{params.exampaperDeleteStart}   


                  and a.is_deleted <= #{params.exampaperDeleteEnd}   


                and a.is_deleted = #{params.isDeleted}




        order by a.${params.orderBy} desc
